    super.$_db,
    super.$_table,
    super.$_typedResult,
  );

  static $CeremonyPlansTable _planIdTable(_$AppDatabase db) =>
      db.ceremonyPlans.createAlias(
        $_aliasNameGenerator(db.ceremonyScenarios.planId, db.ceremonyPlans.id),
      );

  $$CeremonyPlansTableProcessedTableManager get planId {
    final $_column = $_itemColumn<String>('plan_id')!;

    final manager = $$CeremonyPlansTableTableManager(
      $_db,
      $_db.ceremonyPlans,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_planIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<
    $CeremonyBudgetLinesTable,
    List<CeremonyBudgetLineRow>
  >
  _ceremonyBudgetLinesRefsTable(_$AppDatabase db) =>
