                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (ventureIdeasRefs) db.ventureIdeas,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
